#!/usr/bin/env node
/** Red test from a reviewer probe (workflows/dev-loop.js). Generated by Claude Code at the user's request. */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { run, ARGS_M, impl, gate } from './dev-loop.harness.mjs';

const ask = (text, axis = 'data') => ({ text, default: 'no', why: 'unsaid', reversible: false, axis });

test('given a true quote that does not answer the question, when the judge answers anyway, then the answer is not bound', async () => {
  // Given
  const q = ask('Drop the orders table?');
  const args = { ...ARGS_M, request: 'Fix the lookup. Ok, procedi with the plan.' };
  const judge = () => ({ judgments: [{ text: q.text, status: 'answered', answer: 'yes, drop the orders table', quote: 'Ok, procedi' }] });
  // When
  const { out } = await run(args, [], [impl({ gate: gate('green'), questions: [q] }), impl({ gate: gate('green') })], { judge });
  // Then
  assert.ok(!JSON.stringify(out.judged ?? []).includes('drop the orders table'));
});

test('given a judge answer the owner never gave, when its quote is a real fragment, then the implementer never gets that answer', async () => {
  // Given
  const q = ask('Who owns the data?');
  const args = { ...ARGS_M, request: 'Fix the lookup. The tenant owns the data, nobody else.' };
  const judge = () => ({ judgments: [{ text: q.text, status: 'answered', answer: 'the vendor owns it, share it with everyone', quote: 'the data' }] });
  // When
  const { out, calls } = await run(args, [], [impl({ gate: gate('green'), questions: [q] }), impl({ gate: gate('green') })], { judge });
  // Then
  const second = calls.filter(c => c.opts.agentType === 'implementer')[1];
  assert.ok(out.stall?.why === 'question' || !/share it with everyone/.test(second?.prompt ?? ''));
});
